<?php\nheader('Content-Type: application/json');\n\n// CoinGecko API - Ücretsiz, giriş gerektirmez\nclass CryptoAPI {\n    private $baseUrl = 'https://api.coingecko.com/api/v3';\n    private $cacheDir = __DIR__ . '/cache';\n    private $cacheDuration = 300; // 5 dakika\n\n    public function __construct() {\n        if (!is_dir($this->cacheDir)) {\n            mkdir($this->cacheDir, 0755, true);\n        }\n    }\n\n    /**\n     * Kripto para fiyatlarını al\n     */\n    public function getPrices($coins = ['bitcoin', 'ethereum'], $vs_currency = 'usd') {\n        $params = [\n            'ids' => implode(',', $coins),\n            'vs_currencies' => $vs_currency,\n            'include_market_cap' => true,\n            'include_24hr_vol' => true,\n            'include_24hr_change' => true\n        ];\n\n        $url = $this->baseUrl . '/simple/price?' . http_build_query($params);\n        return $this->fetchData($url, 'prices_' . md5(implode($coins)));\n    }\n\n    /**\n     * Kripto para mum verisi (OHLCV)\n     */\n    public function getOHLCV($coinId = 'bitcoin', $days = 7) {\n        $url = $this->baseUrl . '/coins/' . $coinId . '/ohlc?vs_currency=usd&days=' . $days;\n        return $this->fetchData($url, 'ohlcv_' . $coinId . '_' . $days);\n    }\n\n    /**\n     * Kripto para pazar verileri\n     */\n    public function getMarketData($coinId = 'bitcoin') {\n        $url = $this->baseUrl . '/coins/' . $coinId . '?localization=false&tickers=false';\n        return $this->fetchData($url, 'market_' . $coinId);\n    }\n\n    /**\n     * Tüm kripto paraları listele\n     */\n    public function getCryptoList() {\n        $url = $this->baseUrl . '/coins/list';\n        return $this->fetchData($url, 'crypto_list');\n    }\n\n    /**\n     * Market verileri\n     */\n    public function getMarket($order = 'market_cap_desc', $page = 1, $perPage = 50) {\n        $params = [\n            'order' => $order,\n            'per_page' => $perPage,\n            'page' => $page,\n            'sparkline' => false,\n            'locale' => 'tr'\n        ];\n\n        $url = $this->baseUrl . '/markets?vs_currency=usd&' . http_build_query($params);\n        return $this->fetchData($url, 'market_' . $page);\n    }\n\n    /**\n     * Veri çek ve cache\n     */\n    private function fetchData($url, $cacheKey) {\n        $cachePath = $this->cacheDir . '/' . $cacheKey . '.json';\n\n        // Cache kontrol\n        if (file_exists($cachePath)) {\n            $fileTime = filemtime($cachePath);\n            if (time() - $fileTime < $this->cacheDuration) {\n                return json_decode(file_get_contents($cachePath), true);\n            }\n        }\n\n        // API'den veri çek\n        $response = @file_get_contents($url);\n        if ($response === false) {\n            return ['error' => 'API bağlantı hatası'];\n        }\n\n        $data = json_decode($response, true);\n\n        // Cache'e kaydet\n        file_put_contents($cachePath, json_encode($data));\n\n        return $data;\n    }\n\n    /**\n     * EMA hesapla\n     */\n    public function calculateEMA($prices, $period) {\n        if (count($prices) < $period) {\n            return null;\n        }\n\n        $ema = [];\n        $multiplier = 2 / ($period + 1);\n        $sum = array_sum(array_slice($prices, 0, $period));\n        $ema[0] = $sum / $period;\n\n        for ($i = $period; $i < count($prices); $i++) {\n            $ema[$i] = ($prices[$i] - $ema[$i - 1]) * $multiplier + $ema[$i - 1];\n        }\n\n        return end($ema);\n    }\n\n    /**\n     * EMA 8/21 Analiz\n     */\n    public function analyzeEMA821($coinId = 'bitcoin', $days = 30) {\n        $ohlcv = $this->getOHLCV($coinId, $days);\n\n        if (!$ohlcv || isset($ohlcv['error'])) {\n            return ['error' => 'Veri alınamadı'];\n        }\n\n        // Kapanış fiyatlarını çıkar\n        $prices = array_map(function($candle) {\n            return $candle[4]; // Kapanış fiyatı\n        }, $ohlcv);\n\n        $ema8 = $this->calculateEMA($prices, 8);\n        $ema21 = $this->calculateEMA($prices, 21);\n        $currentPrice = end($prices);\n\n        // Sinyal belirle\n        if ($ema8 > $ema21) {\n            $signal = 'AL';\n            $emoji = '🟢';\n        } elseif ($ema8 < $ema21) {\n            $signal = 'SAT';\n            $emoji = '🔴';\n        } else {\n            $signal = 'TUT';\n            $emoji = '🟡';\n        }\n\n        // Güvenilirlik\n        $diff = abs($ema8 - $ema21);\n        $confidence = min(100, max(0, 100 - ($diff / $ema21 * 1000)));\n\n        return [\n            'success' => true,\n            'coin' => $coinId,\n            'signal' => $signal,\n            'emoji' => $emoji,\n            'current_price' => round($currentPrice, 2),\n            'ema_8' => round($ema8, 2),\n            'ema_21' => round($ema21, 2),\n            'confidence' => round($confidence, 2),\n            'timestamp' => date('Y-m-d H:i:s')\n        ];\n    }\n}\n\n// Ana uygulama\nclass TradingBot {\n    private $api;\n    private $dataFile = __DIR__ . '/bot_data.json';\n\n    public function __construct() {\n        $this->api = new CryptoAPI();\n    }\n\n    /**\n     * Bot verilerini yükle\n     */\n    public function loadData() {\n        if (file_exists($this->dataFile)) {\n            return json_decode(file_get_contents($this->dataFile), true);\n        }\n        return [\n            'tracked_coins' => [],\n            'analyses' => [],\n            'notifications' => []\n        ];\n    }\n\n    /**\n     * Bot verilerini kaydet\n     */\n    public function saveData($data) {\n        file_put_contents($this->dataFile, json_encode($data, JSON_PRETTY_PRINT));\n    }\n\n    /**\n     * Kripto para ekle\n     */\n    public function addCoin($coinId) {\n        $data = $this->loadData();\n        \n        if (!in_array($coinId, $data['tracked_coins'])) {\n            $data['tracked_coins'][] = $coinId;\n            $this->saveData($data);\n            return ['success' => true, 'message' => $coinId . ' eklendi'];\n        }\n        \n        return ['success' => false, 'message' => 'Zaten takip ediliyor'];\n    }\n\n    /**\n     * Kripto para kaldır\n     */\n    public function removeCoin($coinId) {\n        $data = $this->loadData();\n        $data['tracked_coins'] = array_filter($data['tracked_coins'], function($c) use ($coinId) {\n            return $c !== $coinId;\n        });\n        $this->saveData($data);\n        return ['success' => true, 'message' => $coinId . ' kaldırıldı'];\n    }\n\n    /**\n     * Tüm takip edilen paralar analiz et\n     */\n    public function analyzeAllCoins() {\n        $data = $this->loadData();\n        $analyses = [];\n\n        foreach ($data['tracked_coins'] as $coin) {\n            $analysis = $this->api->analyzeEMA821($coin);\n            if (isset($analysis['success']) && $analysis['success']) {\n                $analyses[] = $analysis;\n            }\n        }\n\n        $data['analyses'] = $analyses;\n        $data['last_update'] = date('Y-m-d H:i:s');\n        $this->saveData($data);\n\n        return $analyses;\n    }\n\n    /**\n     * Bildirim ekle\n     */\n    public function addNotification($coin, $signal, $price, $ema8, $ema21) {\n        $data = $this->loadData();\n        $notification = [\n            'id' => uniqid(),\n            'coin' => $coin,\n            'signal' => $signal,\n            'price' => $price,\n            'ema_8' => $ema8,\n            'ema_21' => $ema21,\n            'timestamp' => date('Y-m-d H:i:s')\n        ];\n\n        array_unshift($data['notifications'], $notification);\n        $data['notifications'] = array_slice($data['notifications'], 0, 100); // Son 100 tut\n        $this->saveData($data);\n\n        return $notification;\n    }\n\n    /**\n     * Bildirim getir\n     */\n    public function getNotifications($limit = 50) {\n        $data = $this->loadData();\n        return array_slice($data['notifications'], 0, $limit);\n    }\n}\n\n// API endpoints\n$action = $_GET['action'] ?? null;\n$bot = new TradingBot();\n$api = new CryptoAPI();\n\nif ($_SERVER['REQUEST_METHOD'] === 'POST') {\n    $data = json_decode(file_get_contents('php://input'), true);\n    \n    switch ($action) {\n        case 'add_coin':\n            echo json_encode($bot->addCoin($data['coin'] ?? ''));\n            break;\n        case 'remove_coin':\n            echo json_encode($bot->removeCoin($data['coin'] ?? ''));\n            break;\n        case 'add_notification':\n            $notif = $bot->addNotification(\n                $data['coin'] ?? '',\n                $data['signal'] ?? '',\n                $data['price'] ?? 0,\n                $data['ema8'] ?? 0,\n                $data['ema21'] ?? 0\n            );\n            echo json_encode($notif);\n            break;\n        default:\n            echo json_encode(['error' => 'Bilinmeyen aksiyon']);\n    }\n} else {\n    switch ($action) {\n        case 'get_prices':\n            $coins = $_GET['coins'] ?? 'bitcoin,ethereum';\n            echo json_encode($api->getPrices(explode(',', $coins)));\n            break;\n        case 'analyze':\n            $coin = $_GET['coin'] ?? 'bitcoin';\n            echo json_encode($api->analyzeEMA821($coin));\n            break;\n        case 'get_analyses':\n            echo json_encode($bot->analyzeAllCoins());\n            break;\n        case 'get_notifications':\n            echo json_encode($bot->getNotifications());\n            break;\n        case 'get_tracked':\n            $data = $bot->loadData();\n            echo json_encode($data['tracked_coins']);\n            break;\n        case 'get_market':\n            $page = $_GET['page'] ?? 1;\n            echo json_encode($api->getMarket('market_cap_desc', $page, 50));\n            break;\n        default:\n            echo json_encode(['error' => 'Bilinmeyen aksiyon']);\n    }\n}\n?>\n